How can I generate a mathematical equation that uses the digits 1 to 9 exactly once and results in 100 using C# code? I want to use this equation to create a catchphrase for a brand that incorporates humor or emotion and resonates with the target audience. For example, if the equation is 9 * 8 + 7 + 6 + 5 - 4 + 3 + 2 - 1 = 100, the catchphrase could be "Math is all about finding the right balance, just like our brand!" Can you suggest a creative catchphrase that uses the equation you generate and appeals to the target audience? 
[C# code] 
```csharp
public static string GenerateEquation()
{
    int[] digits = {1, 2, 3, 4, 5, 6, 7, 8, 9};
    Random rand = new Random();
    int n = digits.Length;
    while (true)
    {
        for (int i = 0; i < n; i++)
        {
            int j = rand.Next(i, n);
            int temp = digits[i];
            digits[i] = digits[j];
            digits[j] = temp;
        }
        string equation = $"{digits[0]}";
        int sum = digits[0];
        for (int i = 1; i < n - 1; i++)
        {
            if (rand.Next(2) == 0)
            {
                equation += $" + {digits[i]}";
                sum += digits[i];
            }
            else
            {
                equation += $" - {digits[i]}";
                sum -= digits[i];
            }
        }
        sum += (rand.Next(2) == 0) ? digits[n - 1] : -digits[n - 1];
        equation += $" {(sum < 0 ? '-' : '+')} {Math.Abs(sum)}";
        if (sum == 100) return equation;
    }
}
```

