import java.io.*;
import java.net.*;
import javax.net.ssl.*;
public class IoTDataSender {
    public static void main(String[] args) {
        try {
            // Set up SSL context
            SSLContext sslContext = SSLContext.getInstance("TLS");
            sslContext.init(null, null, null);
            SSLSocketFactory sslSocketFactory = sslContext.getSocketFactory();

            // Set up HTTPS connection
            URL url = new URL("https://healthcare-provider.com/data");
            HttpsURLConnection connection = (HttpsURLConnection) url.openConnection();
            connection.setSSLSocketFactory(sslSocketFactory);
            connection.setRequestMethod("POST");
            connection.setRequestProperty("Content-Type", "application/json");
            connection.setDoOutput(true);

            // Set up data to send
            String data = "{\"patient_id\":\"12345\",\"heart_rate\":\"75 bpm\",\"blood_pressure\":\"120/80 mmHg\",\"oxygen_saturation\":\"98%\",\"temperature\":\"98.6°F\",\"timestamp\":\"2022-01-01T12:00:00Z\"}";
            OutputStream outputStream = connection.getOutputStream();
            outputStream.write(data.getBytes());
            outputStream.flush();

            // Get response code
            int responseCode = connection.getResponseCode();
            System.out.println("Response Code: " + responseCode);

            // Close connection
            connection.disconnect();
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}
