```javascript
function generateBlueFruitPhrase() {
  const colors = document.getElementsByTagName("color");
  let sum = 0;
  for (let i = 0; i < colors.length; i++) {
    sum += parseInt(colors[i].getElementsByTagName("hex")[0].textContent.substring(1), 16);
  }
  const firstLetter = sum.toString(16).charAt(0);
  const blueShades = {
    "000080": "navy",
    "0000CD": "medium",
    "0000FF": "blue",
    "0066CC": "sky",
    "0077BE": "crayola",
