  };
  const fruits = ["apple", "banana", "cherry", "date", "elderberry", "fig", "grape", "honeydew", "kiwi", "lemon"];
  const blueShade = blueShades[Object.keys(blueShades).find(key => key.startsWith(firstLetter.toUpperCase()))];
