  dtree.Classify(testData, predictions);
  // Train a neural network model.
  ann::FFN<ann::MeanSquaredError<>, ann::RandomInitialization> model;
  model.Add<ann::Linear<>>(trainData.n_rows, 10);
  model.Add<ann::TanhLayer<>>();
  model.Add<ann::Linear<>>(10, 1);
  model.Train(trainData, trainLabels);
  // Make predictions using the neural network model.
