extension String {
    func syllablesCount() -> Int {
        let vowels = "aeiouy"
        var count = 0
        var lastCharWasVowel = false
        for char in self.lowercased() {
            let strChar = String(char)
            if vowels.contains(strChar) {
                if !lastCharWasVowel {
                    count += 1
                }
                lastCharWasVowel = true
            } else {
                lastCharWasVowel = false
            }
        }
        if self.lowercased().hasSuffix("e") {
            count -= 1
        }
        return count
    }
}
