function findLongestThreeSyllableWord(text) {
  let words = text.split(" ");
  let longestWord = "";
  for(let i = 0; i < words.length; i++) {
    let word = words[i];
    if(countSyllables(word) === 3 && word.charAt(0) !== word.charAt(0).toUpperCase()) {
      if(word.length > longestWord.length) {
        longestWord = word;
      }
    }
  }
  return longestWord;
}
