case class Course(name: String, professor: Professor, assignments: ListBuffer[Assignment])
case class Professor(name: String)
case class Assignment(name: String, deadline: String, isCompleted: Boolean)
case class Extracurricular(name: String, schedule: String)
class Student(val name: String, val courses: ListBuffer[Course], val extracurriculars: ListBuffer[Extracurricular]) {
  def displayCourseSchedule(): Unit = {
    println(s"Course schedule for $name:")
    courses.foreach(course => println(s"${course.name} with Professor ${course.professor.name}"))
  }
  def displayAssignmentSchedule(): Unit = {
    println(s"Assignment schedule for $name:")
    courses.foreach(course => {
      println(s"${course.name}:")
      course.assignments.foreach(assignment => {
        if (!assignment.isCompleted) {
          println(s"${assignment.name} due on ${assignment.deadline}")
        }
      })
    })
  }
  def completeAssignment(courseName: String, assignmentName: String): Unit = {
    courses.find(_.name == courseName).foreach(course => {
      course.assignments.find(_.name == assignmentName).foreach(assignment => {
        assignment.isCompleted = true
        println(s"$name completed ${assignment.name} for ${course.name}")
      })
    })
  }
  def attendExtracurricular(name: String): Unit = {
    extracurriculars.find(_.name == name).foreach(extracurricular => {
      println(s"$name attended ${extracurricular.name} at ${extracurricular.schedule}")
    })
  }
  def simulateDay(): Unit = {
    println(s"$name's daily routine:")
    val random = new Random()
    val course = courses(random.nextInt(courses.length))
    println(s"Attending ${course.name} with Professor ${course.professor.name}")
    val assignment = course.assignments.filter(!_.isCompleted)(random.nextInt(course.assignments.length))
    println(s"Working on ${assignment.name} due on ${assignment.deadline}")
    completeAssignment(course.name, assignment.name)
    val extracurricular = extracurriculars(random.nextInt(extracurriculars.length))
    attendExtracurricular(extracurricular.name)
  }
