	"github.com/danieldk/go-nlptk/naivebayes"
	"github.com/danieldk/go-nlptk/tokenize"
	"strings"
)
func main() {
	// Train the model
	model := naivebayes.NewModel()
	model.AddDocument("positive", tokenize.TextToWords("I love this product!"))
	model.AddDocument("negative", tokenize.TextToWords("This product is terrible."))
	model.Train()
	// Analyze a new text
	text := "I am not sure if I like this product or not."
	words := tokenize.TextToWords(text)
	classification := model.Classify(words)
	// Print the result
	if classification == "positive" {
		fmt.Println("The sentiment of the text is positive.")
	} else {
		fmt.Println("The sentiment of the text is negative.")
	}
}
```
